INSERT INTO posts (id, user_id, title, content, category_id, location, view_count, like_count, comment_count, status, created_at) VALUES (1, 25, '离校手续办理清单', '这条笔记记录一下最近的日常。说实话一开始也没想好怎么开始，就先从最简单的做起，慢慢地居然坚持下来了。过程里有几次想放弃，但看到一点点变化后就又有动力了。如果你也在做类似的事，欢迎留言互相打卡监督！', 9, '苏州', 642, 52, 2, 0, '2026-11-01 22:45:00');
