INSERT INTO posts (id, user_id, title, content, category_id, location, view_count, like_count, comment_count, status, created_at) VALUES (2, 30, '高效学习法分享，让你事半功倍', '关于这个话题，我的看法是这样的。不夸张地说，改变了我。网上有很多说法，但我结合自己的体验，觉得最重要的是找到适合自己的节奏，别人的方法可以参考但不必照搬。以下是我踩过的三个坑和对应的解决办法，供大家避雷。', 1, '青岛', 138, 24, 4, 0, '2026-10-17 22:48:00');
