INSERT INTO posts (id, user_id, title, content, category_id, location, view_count, like_count, comment_count, status, created_at) VALUES (3, 11, '我为什么不焦虑了', '整理了一份超详细的入门攻略，从零基础到入门亲测有效。仅供参考哈～全文比较长，先讲思路再讲步骤，建议先收藏再看。文中的资料都是我自己用过的，没有废话，直接上干货。觉得有用的话点个赞让更多人看到～', 8, '厦门', 455, 23, 6, 0, '2026-10-31 20:57:00');
