INSERT INTO posts (id, user_id, title, content, category_id, location, view_count, like_count, comment_count, status, created_at) VALUES (114, 30, '关于xxx现象的一些思考', '大家好，今天想分享一些最近的实践心得。一句话总结：坚持就是胜利。经过一段时间的摸索，我总结了几个关键点：第一，目标要拆解成可执行的小步骤；第二，建立自己的反馈机制，每周复盘一次；第三，不要追求完美主义，先完成再优化。希望这些经验对大家有帮助，有问题欢迎评论区交流～', 8, '长沙', 96, 49, 7, 0, '2026-11-11 20:11:00');
