INSERT INTO posts (id, user_id, title, content, category_id, location, view_count, like_count, comment_count, status, created_at) VALUES (124, 35, '书法练习日记，一笔一划皆修行', '这条笔记记录一下最近的日常。一句话总结：坚持就是胜利。说实话一开始也没想好怎么开始，就先从最简单的做起，慢慢地居然坚持下来了。过程里有几次想放弃，但看到一点点变化后就又有动力了。如果你也在做类似的事，欢迎留言互相打卡监督！', 4, '青岛', 707, 41, 12, 0, '2026-11-04 17:18:00');
